sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var html;
    var gr = new GlideRecord('x_ndecd_triage_2_0_pdftemplate');
    gr.addQuery('template_name', 'TSA/CS CAA');
    gr.query();
    if (gr.next()) {
        html = gr.html_template;
    }

    var eleve = new GlideRecord('x_ndecd_triage_2_0_eleve');
    eleve.get(current.getValue('eleve'));
    html = html.replace('var1', eleve.name); //Name
    html = html.replace('var2', eleve.u_date_de_naissance); //Birthdate
    html = html.replace('var3', eleve.u_niso); //NISO
    html = html.replace('var4', eleve.getDisplayValue('u_nom_de_l_cole')); //School name
    html = html.replace('var5', eleve.getDisplayValue('u_classe')); //Class

	if (current.est_ce_que_l_l_ve_fr_quente_pr_sentement_une_classe_distincte == 'yes') {
		html = html.replace('var6', 'Oui');
	} else {
		html = html.replace('var6', 'Non');
	}

    //html = html.replace('var7', current.classe_distinct);
    html = html.replace('var8', current.est_ce_que_l_l_ve_a_un_diagnostic_pos_par_un_professionnel_de_la_sant_autoris);
    html = html.replace('var9', current.situation_familiale_de_l_l_ve);
    //html = html.replace('var10');

	if (current.est_ce_que_le_formulaire_d_aiguillage_services_orthophoniques_r_gulier_vs_volet == 'yes') {
		html = html.replace('var11', 'Oui');
	} else {
		html = html.replace('var11', 'Non');
	}

    html = html.replace('var12', current.getDisplayValue('quel_est_le_motif_de_la_demande_ortho'));

    var value = new GlideRecord('x_ndecd_cecce_base_motif_tsa_cs_caa');
    value.get(current.getValue('quel_est_le_motif_de_la_demande_ortho'));

    if (value.order == '0') {
        html = html.replace('var13', current.nom_du_professionnel_de_la_sant_ayant_fait_la_recommandation);
        html = html.replace('var14', current.titre_du_professionnel_de_la_sant_ayant_fait_la_recommandation);
        html = html.replace('var15', current.date_du_rapport_contenant_la_recommandation);
    } else {
        html = html.replace('Nom du professionnel de la santé ayant fait la recommandation:', '');
        html = html.replace('var13', '');
        html = html.replace('Titre du professionnel de la santé ayant fait la recommandation:', '');
        html = html.replace('var14', '');
        html = html.replace('Date du rapport contenant la recommandation:', '');
        html = html.replace('var15', '');
    }

    html = html.replace("var20", current.getDisplayValue('opened_by'));
    html = html.replace("var20", current.getDisplayValue('opened_by'));
    html = html.replace("var21", current.getDisplayValue('sys_created_on'));

    var opened_by_title = new GlideRecord('sys_user');
    opened_by_title.addQuery('sys_id', current.opened_by.sys_id);
    opened_by_title.query();
    if (opened_by_title.next()) {
        html = html.replace("var22", opened_by_title.getDisplayValue('title'));
    }

    var dir = current.number;
    var gsdirect = new GlideRecord('sysapproval_approver');
    gsdirect.addQuery('sysapproval.number', dir);
    gsdirect.addQuery('state', 'approved');
    gsdirect.query();
    while (gsdirect.next()) {
        html = html.replace("var90", gsdirect.getDisplayValue('approver'));
        html = html.replace("var91", gsdirect.getDisplayValue('approver'));
    }
    html = html.replace("var92", current.getDisplayValue('sys_updated_on'));

    pdf_name = 'Consentement TSA/CS CAA ' + eleve.name;
    table_name = 'x_ndecd_triage_2_0_demande_tsa_cs_caa';
    table_sys_id = current.sys_id;

    var hfInfo = {
        HeaderImageAttachmentId: "fe71ca801b04b910d991c882604bcb30",
        HeaderImageAlignment: "left",
        FooterImageAttachmentId: "f69aa9661bf7a5108d594047bc4bcb1c",
        FooterImageAlignment: "TOP_CENTER",
        PageSize: "A4",
        GeneratePageNumber: "false",
        TopOrBottomMargin: "50",
        LeftOrRightMargin: "24"
    };

    var v = new sn_pdfgeneratorutils.PDFGenerationAPI;
    var result = v.convertToPDFWithHeaderFooter(html, table_name, table_sys_id, pdf_name, hfInfo);
    current.update();

})(current, previous);
